#include <stdio.h>

int main(void)
{
    int count[11] = {0}, a[] = {1,12,23}, collisions = 0;
    for (int i=0;i<3;i++) { if (count[a[i]%11]++ > 0) { collisions++; } }
    printf("%d\n",collisions);
    return 0;
}

